<script lang="ts">
import {translatedName} from './localization';

 import {languageOverrides} from "./localization";
 import {today,type Project,type Account,type PhysicalMeter} from './model';import {holderAt,propertyDetails,accountCharacteristics,residentsAt,servicesAt,accountOpenOn,statusLabel,citizenName} from './account-data';import {meterConnectedOn,entryConsumption} from './meter-entry';import {displayDate} from './date-format';import {translator} from './i18n';import {History,ChevronDown,Search,X,Plus,Trash2,FileText,Pencil} from "./icons";import type {ReferenceKind} from './catalog-definitions';
 export let project:Project;export let accountId:string;export let initialDate=today();export let onclose:()=>void;export let ondocument:(kind:string,a:Account,subject?:string,date?:string)=>void;export let onhistory:(type:string,subject?:string)=>void;export let onreference:(kind:ReferenceKind,id:string)=>void;export let onreport:(kind:string,date:string)=>void;
 let date=initialDate,tab='main',selectedResident='',selectedService='',selectedMeter='',selectedAdditional='',selectedCharacteristic='',menu='';
 $:t=translator(project.settings.language,$languageOverrides);$:a=project.accounts.find(a=>a.id===accountId);$:holder=a?holderAt(project,a,date):{id:'',name:''};$:details=a?propertyDetails(project,a):null;$:characteristics=a?accountCharacteristics(project,a,date):null;$:residents=a?residentsAt(project,a,date):[];$:services=a?servicesAt(project,a,date):[];
 $:meters=project.meters.filter(m=>m.account_id===accountId||m.scope==='shared'&&m.account_links?.some(l=>l.account_id===accountId&&l.date<=date));
 $:additional=(()=>{const rows=new Map<string,Project['account_history']['additional'][number]>();for(const row of project.account_history.additional.filter(r=>r.account_id===accountId&&r.date<=date).sort((a,b)=>a.date.localeCompare(b.date)))rows.set(row.property_id,row);return [...rows.values()];})();
 function history(type:string,subject?:string){menu='';onhistory(type,subject);}
 function documentAction(kind:string,a:Account,subject?:string){ondocument(kind,a,subject,date);}
 function change(){if(!a)return;if(tab==='residents')documentAction('residents',a,selectedResident);else if(tab==='services')documentAction('services',a,selectedService);else if(tab==='meters')documentAction('meter-status',a,selectedMeter);else if(tab==='additional')documentAction('additional',a,selectedAdditional);}
 function lastReading(id:string){return project.meter_values.filter(r=>r.meter_id===id&&r.reading_date<=date).sort((a,b)=>b.reading_date.localeCompare(a.reading_date))[0];}
 function connected(meter:PhysicalMeter){return meterConnectedOn(meter,date)&&(meter.scope==='individual'||!![...(meter.account_links||[])].filter(l=>l.account_id===accountId&&l.date<=date).sort((a,b)=>b.date.localeCompare(a.date))[0]?.active);}
 function previousReading(id:string){return project.meter_values.filter(r=>r.meter_id===id&&r.reading_date<=date).sort((a,b)=>b.reading_date.localeCompare(a.reading_date))[1];}
</script>
<svelte:window onclick={e=>{if(!(e.target instanceof Element)||!e.target.closest('.account-popup'))menu='';}}/>
<div class="account-card">{#if a}
 <div class="date-line"><label>{t('На дату','La data')}<input type="date" bind:value={date}/></label><span>{t('Номер лицевого счёта:','Număr cont:')} <strong>{a.number}</strong></span></div>
 <div class="holder-line"><span>{t('Ответственный квартиросъёмщик:','Titular responsabil:')}</span><input readonly value={holder.name}/><button class="small-command" title={t('Открыть гражданина','Deschide cetățeanul')} disabled={!holder.id} onclick={()=>onreference('citizens',holder.id)}><Search size={15}/></button><button class="small-command" onclick={()=>history('holder')}><History size={15}/>{t('История','Istoric')}</button></div>
 <nav class="tabs">{#each [['main','Основное','Principal'],['residents','Проживающие','Locatari'],['services','Услуги','Servicii'],['meters','Приборы учёта','Contoare'],['additional','Дополнительные объекты учёта','Obiecte suplimentare'],['characteristics','Характеристики','Caracteristici']] as item}<button class:chosen={tab===item[0]} onclick={()=>{tab=item[0];menu='';}}>{project.settings.language==='ru'?item[1]:item[2]}</button>{/each}</nav>
 <section class="tab-content">
 {#if tab==='main'}
  <div class="property-line">{t('Объект учёта:','Obiect:')}<button class="link" disabled={!details?.property} onclick={()=>details?.property&&onreference('properties',details.property.id)}>{details?.property?.name||a.address}</button></div>
  <div class="address-grid"><span>{t('Населённый пункт:','Localitate:')}</span><button class="link" disabled={!details?.locality} onclick={()=>details?.locality&&onreference('localities',details.locality.id)}>{details?.locality?.name||'—'}</button><span>{t('Здание:','Clădire:')}</span><button class="link" disabled={!details?.building} onclick={()=>details?.building&&onreference('buildings',details.building.id)}>{details?.building?.attributes.number||details?.building?.name||'—'}</button><span>{t('Улица:','Stradă:')}</span><button class="link" disabled={!details?.street} onclick={()=>details?.street&&onreference('streets',details.street.id)}>{details?.street?.name||'—'}</button><span>{t('Номер:','Număr:')}</span><span>{details?.property?.attributes.number||a.apartments.join(', ')||'—'}</span></div>
  <table><thead><tr><th>{t('Характеристика','Caracteristică')}</th><th>{t('Значение','Valoare')}</th></tr></thead><tbody>{#each [[t('Количество проживающих','Număr locatari'),characteristics?.people],[t('Количество зарегистрированных','Număr persoane înregistrate'),characteristics?.registered],[t('Этаж','Etaj'),characteristics?.floor],[t('Общая площадь','Suprafață totală'),characteristics?.total],[t('Жилая площадь','Suprafață locuibilă'),characteristics?.living]] as row}<tr><td>{row[0]}</td><td>{row[1]??'—'}</td></tr>{/each}</tbody></table>
  <strong class="account-status">{date<(a.opening_date||a.opening_period+'-01')?t('Лицевой счёт ещё не открыт. Дата открытия ','Contul nu este încă deschis. Data deschiderii '):accountOpenOn(a,date)?t('Лицевой счёт открыт. Дата открытия ','Cont deschis. Data deschiderii '):t('Лицевой счёт закрыт. Дата закрытия ','Cont închis. Data închiderii ')}{displayDate(date<(a.opening_date||a.opening_period+'-01')||accountOpenOn(a,date)?a.opening_date||a.opening_period+'-01':a.closing_date||a.opening_date||a.opening_period+'-01',project)}</strong>
 {:else if tab==='characteristics'}
  <div class="commands"><button onclick={()=>documentAction('characteristics',a)}><Plus size={16}/>{t('Добавить','Adaugă')}</button><button disabled={!selectedCharacteristic} onclick={()=>documentAction('characteristics-delete',a,selectedCharacteristic)}><Trash2 size={16}/>{t('Удалить','Elimină')}</button><button onclick={()=>documentAction('information',a)}><Pencil size={16}/>{t('Изменить основные характеристики','Modifică caracteristicile principale')}</button></div><table><thead><tr><th>{t('Характеристика','Caracteristică')}</th><th>{t('Значение','Valoare')}</th></tr></thead><tbody>{#each characteristics?.custom||[] as row}<tr class:selected={selectedCharacteristic===row.name} onclick={()=>selectedCharacteristic=row.name}><td>{row.name}</td><td>{row.value}</td></tr>{/each}</tbody></table>
 {:else}
  <div class="commands"><div class="account-popup"><button onclick={()=>menu=menu==='history'?'':'history'}><History size={15}/>{t('История','Istoric')}<ChevronDown size={13}/></button>{#if menu==='history'}<div class="popup">{#if tab==='residents'}<button disabled={!selectedResident} onclick={()=>history('registration',selectedResident)}>{t('Вид регистрации','Tip de înregistrare')}</button><button disabled={!selectedResident} onclick={()=>history('residence',selectedResident)}>{t('Статус проживания','Starea locuirii')}</button>{:else if tab==='meters'}{#each [['meter-status','Статус прибора учёта','Starea contorului'],['meter-readings','Показания прибора учёта','Indexuri contor'],['meter-consumption','Объём потребления по прибору учёта','Volum consum contor']] as option}<button disabled={!selectedMeter} onclick={()=>history(option[0],selectedMeter)}>{project.settings.language==='ru'?option[1]:option[2]}</button>{/each}{:else}<button onclick={()=>history(tab,tab==='services'?selectedService:selectedAdditional)}>{t('История статусов','Istoricul stărilor')}</button>{/if}</div>{/if}</div><button onclick={change}><Pencil size={15}/>{t('Изменить статус','Modifică starea')}</button></div>
  {#if tab==='residents'}<table><thead><tr><th>{t('Проживающий','Locatar')}</th><th>{t('Вид регистрации','Tip de înregistrare')}</th><th>{t('Статус проживания','Starea locuirii')}</th><th>{t('Родство','Rudenie')}</th><th>{t('Категория льготы','Categorie facilități')}</th></tr></thead><tbody>{#each residents as row}<tr class:selected={selectedResident===row.id} onclick={()=>selectedResident=row.id} ondblclick={()=>onreference('citizens',row.id)}><td>{row.name}</td><td>{statusLabel(row.registration,'registration',project.settings.language==='ro')}</td><td>{statusLabel(row.residence,'residence',project.settings.language==='ro')}</td><td>{row.relationship}</td><td>{project.reference_catalogs['benefit-categories']?.find(c=>c.id===row.benefit)?.name||''}</td></tr>{/each}</tbody></table>
  {:else if tab==='services'}<table><thead><tr><th>{t('Статус','Stare')}</th><th>{t('Услуга','Serviciu')}</th><th>{t('Вид тарифа','Tip tarif')}</th></tr></thead><tbody>{#each services as row}<tr class:selected={selectedService===row.service.id} onclick={()=>selectedService=row.service.id} ondblclick={()=>onreference('tariff-types',row.tariff_type_id)}><td>{row.active?'✓':'—'}</td><td>{translatedName(row.service.name,project.settings.language,$languageOverrides)}</td><td>{project.reference_catalogs['tariff-types']?.find(r=>r.id===row.tariff_type_id)?.name||'—'}</td></tr>{/each}</tbody></table>
  {:else if tab==='meters'}<table><thead><tr><th>{t('Прибор учёта','Contor')}</th><th>{t('Тип счётчика','Tip contor')}</th><th>{t('Статус','Stare')}</th><th>{t('Показание','Index')}</th><th>{t('Объём','Volum')}</th></tr></thead><tbody>{#each meters as meter}{@const reading=lastReading(meter.id)}{@const previous=previousReading(meter.id)}<tr class:selected={selectedMeter===meter.id} onclick={()=>selectedMeter=meter.id} ondblclick={()=>history('meter-readings',meter.id)}><td>{meter.label}</td><td>{meter.scope==='shared'?t('Коллективный','Colectiv'):t('Индивидуальный','Individual')}</td><td>{connected(meter)?t('Подключён','Conectat'):t('Не подключён','Deconectat')}</td><td>{reading?.value??meter.initial_value}</td><td>{entryConsumption(previous?.value??meter.initial_value,reading?.value||'')??'—'}</td></tr>{/each}</tbody></table>
  {:else}<table><thead><tr><th>{t('Статус','Stare')}</th><th>{t('Объект учёта','Obiect')}</th></tr></thead><tbody>{#each additional as row}<tr class:selected={selectedAdditional===row.property_id} onclick={()=>selectedAdditional=row.property_id} ondblclick={()=>onreference('properties',row.property_id)}><td>{row.active?'✓':'—'}</td><td>{project.reference_catalogs.properties?.find(r=>r.id===row.property_id)?.name||row.property_id}</td></tr>{/each}</tbody></table>{/if}
 {/if}
 </section>
 <footer><div class="account-popup"><button class="small-command" onclick={()=>menu=menu==='reports'?'':'reports'}><FileText size={16}/>{t('Отчёты','Rapoarte')}<ChevronDown size={13}/></button>{#if menu==='reports'}<div class="popup reports-popup">{#each [['receipts','Квитанция','Factură'],['account-ledger','Карточка расчётов','Fișă de calcul'],['reports','Оборотно-сальдовая ведомость','Balanță de verificare'],['service-reports','Ведомость по услугам','Balanță pe servicii'],['payment-report','Отчёт по оплате','Raport de plăți']] as report}<button onclick={()=>{menu='';onreport(report[0],date);}}>{project.settings.language==='ru'?report[1]:report[2]}</button>{/each}</div>{/if}</div><button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer>
 {:else}<p>{t('Лицевой счёт не найден.','Contul nu a fost găsit.')}</p>{/if}</div>
<style>.account-card{display:flex;flex-direction:column;gap:12px;padding:16px;min-width:0;min-height:100%;box-sizing:border-box}.date-line{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.date-line label{display:flex;align-items:center;gap:8px}.holder-line{display:flex;gap:4px;align-items:center}.holder-line>span{flex-shrink:0;margin-right:8px}.holder-line input{min-width:0;flex:1}.small-command,.commands button,.tabs button{display:flex;align-items:center;gap:5px;background:transparent;border:0;color:var(--text);padding:7px}.small-command:hover,.commands button:hover{background:var(--hover)}.tabs{display:flex;gap:2px;border-bottom:1px solid var(--border);flex-wrap:wrap}.tabs button.chosen{box-shadow:inset 0 -2px var(--accent);background:var(--hover)}.tab-content{flex:1;min-height:280px;min-width:0;overflow:auto}.property-line{display:flex;gap:20px;border-bottom:1px solid var(--border);padding:8px 0 12px}.address-grid{display:grid;grid-template-columns:135px 1fr 90px 1fr;gap:12px;padding:16px 0}.link{color:var(--accent);background:none;border:0;text-align:left;padding:0}.link:disabled{color:var(--text);opacity:1}.account-status{display:block;margin-top:14px}.commands{display:flex;gap:8px;align-items:center}table{width:100%;border-collapse:collapse}th,td{padding:7px;text-align:left}th{background:#80808018;font-weight:600}tbody tr.selected{background:#489bcb30}footer{display:flex;justify-content:flex-end;gap:8px;align-items:center}.account-popup{position:relative}.popup{position:absolute;top:100%;left:0;min-width:240px;z-index:30;background:var(--surface);box-shadow:0 6px 20px #0003;padding:5px}.popup button{width:100%;text-align:left;padding:9px;white-space:nowrap}.reports-popup{top:auto;bottom:100%;left:auto;right:0}.reports-popup button{display:block;background:none;border:0;color:var(--text)}.reports-popup button:hover{background:var(--hover)}</style>
